import React, { useState } from 'react';
import { Rating, SeafoodResultItem } from '../types';

interface DonutChartByVolumeProps {
  data: { [key in Rating]?: { value: number; items: SeafoodResultItem[] } };
  metric: 'volume' | 'count';
  onSegmentClick: (title: string, data: SeafoodResultItem[]) => void;
}

const ratingOrder: Rating[] = [Rating.BestChoice, Rating.GoodAlternative, Rating.Avoid, Rating.Certified, Rating.NA];

const ratingColors: { [key in Rating]: string } = {
  [Rating.BestChoice]: '#23872B',
  [Rating.GoodAlternative]: '#BA8C17',
  [Rating.Avoid]: '#AA323C',
  [Rating.Certified]: '#00629B',
  [Rating.NA]: '#9ca3af',
};

const DonutChartByVolume: React.FC<DonutChartByVolumeProps> = ({ data, metric, onSegmentClick }) => {
  const [hoveredSegment, setHoveredSegment] = useState<Rating | null>(null);

  const totalValue = (Object.values(data) as { value: number; items: SeafoodResultItem[] }[]).reduce((acc, curr) => acc + (curr?.value || 0), 0);

  // We only show the "not enough data" message if totalValue is 0 AND metric is volume (implying missing volume data).
  // If metric is count, totalValue should be > 0 if there are results.
  if (totalValue === 0) {
      return (
         <div className="bg-white p-6 rounded-lg shadow-lg border border-gray-200">
             <h2 className="text-xl font-bold text-gray-800 mb-4">Ratings by {metric === 'volume' ? 'Volume' : 'Count'}</h2>
            <p className="text-gray-500 text-center py-8">
                {metric === 'volume' 
                    ? "Not enough data to display this chart. Make sure you have mapped the 'Volume' column." 
                    : "No data available."}
            </p>
        </div>
      );
  }

  const radius = 40;
  const strokeWidth = 15;
  const normalizedRadius = radius - strokeWidth / 2;
  const circumference = normalizedRadius * 2 * Math.PI;
  let accumulatedAngle = 0;

  const chartData = ratingOrder
    .map(rating => {
        const segmentData = data[rating];
        if (!segmentData || segmentData.value === 0) return null;

        const percentage = (segmentData.value / totalValue) * 100;
        const strokeDashoffset = circumference - (percentage / 100) * circumference;
        const rotation = accumulatedAngle;
        accumulatedAngle += (percentage / 100) * 360;

        return {
            rating,
            value: segmentData.value,
            items: segmentData.items,
            percentage,
            color: ratingColors[rating],
            strokeDashoffset,
            rotation
        };
    })
    .filter((segment): segment is NonNullable<typeof segment> => segment !== null);

    const handleKeyDown = (e: React.KeyboardEvent, rating: Rating, items: SeafoodResultItem[]) => {
        if (e.key === 'Enter' || e.key === ' ') {
            e.preventDefault();
            onSegmentClick(rating, items);
        }
    };


  return (
    <div className="bg-white p-6 rounded-lg shadow-lg border border-gray-200">
        <h2 className="text-xl font-bold text-gray-800 mb-4">Ratings by {metric === 'volume' ? 'Volume' : 'Product Count'}</h2>
        {/* Centered layout */}
        <div className="flex flex-col md:flex-row items-center justify-center gap-8">
            {/* Increased chart size from w-48 to w-64 */}
            <div className="relative w-64 h-64 flex-shrink-0">
                <svg
                    height="100%"
                    width="100%"
                    viewBox="0 0 100 100"
                    className="-rotate-90"
                    role="img"
                    aria-label={`Donut chart showing ratings by ${metric}. Total is ${totalValue.toLocaleString()}.`}
                >
                    <circle
                        stroke="#e5e7eb"
                        cx="50"
                        cy="50"
                        r={normalizedRadius}
                        fill="transparent"
                        strokeWidth={strokeWidth}
                    />
                {chartData.map(segment => (
                    <g 
                        key={segment.rating} 
                        className="cursor-pointer focus:outline-none" 
                        onClick={() => onSegmentClick(segment.rating, segment.items)}
                        onMouseEnter={() => setHoveredSegment(segment.rating)}
                        onMouseLeave={() => setHoveredSegment(null)}
                        onKeyDown={(e) => handleKeyDown(e, segment.rating, segment.items)}
                        role="button"
                        tabIndex={0}
                        aria-label={`${segment.rating}: ${segment.value.toLocaleString()} ${metric}, ${segment.percentage.toFixed(1)}%`}
                    >
                        <circle
                            stroke={segment.color}
                            cx="50"
                            cy="50"
                            r={normalizedRadius}
                            fill="transparent"
                            strokeWidth={strokeWidth + (hoveredSegment === segment.rating ? 2 : 0)}
                            strokeDasharray={`${circumference} ${circumference}`}
                            style={{ strokeDashoffset: segment.strokeDashoffset, transform: `rotate(${segment.rotation}deg)`, transformOrigin: '50% 50%' }}
                            className="transition-all duration-300"
                        />
                    </g>
                ))}
                </svg>
                <div className="absolute inset-0 flex flex-col items-center justify-center text-center pointer-events-none">
                    <span className="text-3xl font-bold text-gray-800">{totalValue.toLocaleString()}</span>
                    <span className="text-sm text-gray-500">Total {metric === 'volume' ? 'Volume' : 'Products'}</span>
                </div>
            </div>

            {/* Labels grid layout closer to legend */}
            <div className="space-y-3">
                {chartData.map(segment => (
                <div 
                    key={segment.rating} 
                    className="grid grid-cols-[auto_auto] gap-x-6 gap-y-1 items-center text-sm cursor-pointer p-2 rounded-md transition-colors"
                    onClick={() => onSegmentClick(segment.rating, segment.items)}
                    onMouseEnter={() => setHoveredSegment(segment.rating)}
                    onMouseLeave={() => setHoveredSegment(null)}
                    style={{ backgroundColor: hoveredSegment === segment.rating ? '#f3f4f6' : 'transparent' }}
                >
                    <div className="flex items-center gap-2">
                        <span className="w-4 h-4 rounded-full" style={{ backgroundColor: segment.color }}></span>
                        <span className="font-medium text-gray-700">{segment.rating}</span>
                    </div>
                    <div className="font-semibold text-gray-800 text-right">
                        {segment.value.toLocaleString()}
                        <span className="ml-2 font-normal text-gray-500">({segment.percentage.toFixed(1)}%)</span>
                    </div>
                </div>
                ))}
            </div>
        </div>
    </div>
  );
};

export default DonutChartByVolume;

import React, { useMemo, useState } from 'react';
import { SeafoodResultItem, Rating } from '../types';
import DonutChartByVolume from './DonutChartByVolume';
import StackedBarChart, { BarChartDataItem } from './StackedBarChart';

interface ChartsViewProps {
  results: SeafoodResultItem[];
  columnMapping: Record<string, string>;
  onSegmentClick: (title: string, data: SeafoodResultItem[]) => void;
}

type GroupedData = Record<string, {
  totalValue: number;
  breakdown: { [key in Rating]?: number };
  sourceItems: SeafoodResultItem[];
}>;

type ChartType = 'species' | 'country' | 'supplier';
type MetricType = 'volume' | 'count';

const ChartsView: React.FC<ChartsViewProps> = ({ results, columnMapping, onSegmentClick }) => {
  const [activeChart, setActiveChart] = useState<ChartType>('species');
  const [metric, setMetric] = useState<MetricType>('volume');

  const getMappedKey = (field: string) => Object.keys(columnMapping).find(key => key === field) ? columnMapping[field] : null;

  const volumeKey = getMappedKey('Volume');
  const speciesKey = getMappedKey('Common name');
  const countryKey = getMappedKey('Source country');
  const supplierKey = getMappedKey('Supplier');

  const { donutData, speciesData, countryData, supplierData } = useMemo(() => {
    // Helper to get value based on metric
    const getValue = (item: SeafoodResultItem) => {
        if (metric === 'count') return 1;
        if (!volumeKey || item[volumeKey] === undefined) return 0;
        const volume = parseFloat(String(item[volumeKey]));
        return isNaN(volume) ? 0 : volume;
    };

    // --- Process for Donut Chart ---
    const donutData: { [key in Rating]?: { value: number; items: SeafoodResultItem[] } } = {};
    results.forEach(item => {
        const rating = item.rating;
        if (!donutData[rating]) {
            donutData[rating] = { value: 0, items: [] };
        }
        donutData[rating]!.value += getValue(item);
        donutData[rating]!.items.push(item);
    });

    // --- Process for Bar Charts ---
    const processGroupData = (key: string | null): BarChartDataItem[] => {
      if (!key) return [];

      const grouped = results.reduce((acc, item) => {
        const groupLabel = item[key] ? String(item[key]) : 'Unknown';
        if (!acc[groupLabel]) {
          acc[groupLabel] = { totalValue: 0, breakdown: {}, sourceItems: [] };
        }

        const value = getValue(item);
        acc[groupLabel].totalValue += value;
        acc[groupLabel].breakdown[item.rating] = (acc[groupLabel].breakdown[item.rating] || 0) + value;
        acc[groupLabel].sourceItems.push(item);

        return acc;
      }, {} as GroupedData);

      return Object.entries(grouped)
        .map(([label, data]) => ({ label, ...(data as GroupedData[string]) }))
        .sort((a, b) => b.totalValue - a.totalValue)
        .slice(0, 20); // Limit to top 20 by volume/count
    };

    const speciesData = processGroupData(speciesKey);
    const countryData = processGroupData(countryKey);
    const supplierData = processGroupData(supplierKey);

    return { donutData, speciesData, countryData, supplierData };
  }, [results, volumeKey, speciesKey, countryKey, supplierKey, metric]);

  const renderActiveChart = () => {
    switch (activeChart) {
      case 'country':
        return <StackedBarChart title={`Ratings by Source Country (Top 20 by ${metric === 'volume' ? 'Volume' : 'Count'})`} data={countryData} metric={metric} onSegmentClick={onSegmentClick} />;
      case 'supplier':
        return <StackedBarChart title={`Ratings by Supplier (Top 20 by ${metric === 'volume' ? 'Volume' : 'Count'})`} data={supplierData} metric={metric} onSegmentClick={onSegmentClick} />;
      case 'species':
      default:
        return <StackedBarChart title={`Ratings by Species Common Name (Top 20 by ${metric === 'volume' ? 'Volume' : 'Count'})`} data={speciesData} metric={metric} onSegmentClick={onSegmentClick} />;
    }
  };

  return (
    <div className="space-y-8 relative">
       {/* Top Metrics Toggle - Positioned top right or simply at the top */}
       <div className="flex flex-col sm:flex-row justify-between items-center gap-4 mb-4">
            <div className="flex items-center gap-2 bg-gray-100 p-1 rounded-lg border border-gray-200">
                <span className="text-xs font-semibold text-gray-500 px-2 uppercase tracking-wide">Metric:</span>
                 <button 
                    onClick={() => setMetric('volume')}
                    className={`px-3 py-1.5 text-sm font-medium rounded-md transition-all focus:outline-none ${metric === 'volume' ? 'bg-white text-[#00629B] shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}
                >
                    Volume
                </button>
                <button 
                    onClick={() => setMetric('count')}
                    className={`px-3 py-1.5 text-sm font-medium rounded-md transition-all focus:outline-none ${metric === 'count' ? 'bg-white text-[#00629B] shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}
                >
                    # Products
                </button>
            </div>
       </div>

      <DonutChartByVolume data={donutData} metric={metric} onSegmentClick={onSegmentClick} />

      <div className="space-y-4">
        <div className="flex justify-center sm:justify-end">
          <div className="inline-flex bg-gray-100 p-1 rounded-lg border border-gray-200">
              <button 
                  onClick={() => setActiveChart('species')}
                  className={`px-4 py-2 text-sm font-medium rounded-md transition-all focus:outline-none ${activeChart === 'species' ? 'bg-white text-[#00629B] shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}
              >
                  By Species
              </button>
              <button 
                  onClick={() => setActiveChart('country')}
                  className={`px-4 py-2 text-sm font-medium rounded-md transition-all focus:outline-none ${activeChart === 'country' ? 'bg-white text-[#00629B] shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}
              >
                  By Country
              </button>
              <button 
                  onClick={() => setActiveChart('supplier')}
                  className={`px-4 py-2 text-sm font-medium rounded-md transition-all focus:outline-none ${activeChart === 'supplier' ? 'bg-white text-[#00629B] shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}
              >
                  By Supplier
              </button>
          </div>
        </div>

        {renderActiveChart()}
      </div>
    </div>
  );
};

export default ChartsView;

