import { GoogleGenAI, Type } from "@google/genai";
import { SeafoodInputItem, SeafoodResultItem, Rating } from "../types";

// This declaration is necessary because the library is loaded from a script tag in index.html
declare var process: {
  env: {
    API_KEY: string;
  };
};

// Schema for a single analysis result
const singleItemSchema = {
  type: Type.OBJECT,
  properties: {
    uniqueId: {
      type: Type.STRING,
      description: "The Seafood Watch Recommendation ID matching the analysis. Use 'N/A' if Certified or if no specific ID is found.",
    },
    rating: {
      type: Type.STRING,
      enum: [Rating.BestChoice, Rating.GoodAlternative, Rating.Avoid, Rating.Certified, Rating.NA],
      description: "The Seafood Watch environmental rating.",
    },
    reliabilityScore: {
      type: Type.NUMBER,
      description: "A confidence score from 0 to 100 for the rating accuracy.",
    },
    notes: {
      type: Type.STRING,
      description: "Explanation for the rating, especially if data is missing or ambiguous.",
    },
  },
  required: ["uniqueId", "rating", "reliabilityScore", "notes"],
};

// Schema for the batched response, which is an array of single items
const responseSchema = {
    type: Type.ARRAY,
    items: singleItemSchema
};

const systemInstruction = `You are a highly specialized data analyst for the Monterey Bay Aquarium Seafood Watch program. Your sole purpose is to evaluate seafood product information and assign an official Seafood Watch rating. You must use your internal knowledge of the program's standards, which consider species, fishing/farming methods, and geographic origin.

Task:
You will be given an array of seafood product data objects. For EACH object in the array, perform the following analysis:
1. **Certified Rating Rule (Top Priority):** If the input data for an item includes a non-empty value in a 'Certification' field AND your internal Seafood Watch data indicates that this species ('Common name') is eligible for certification (i.e., it has a 'CERT' recommendation type), you MUST assign the rating "Certified". This rating takes precedence over all other ratings. When this rule applies, the notes must follow this exact format: "{Wild or Farmed} {Common name} that is certified by the {Certification} is recognized by Seafood Watch". Use the values from the input data for {Wild or Farmed}, {Common name}, and {Certification}. If a value for {Wild or Farmed} is not available, use "Seafood" in its place. Set the uniqueId to 'N/A' for Certified items.
2. If the Certified rule does not apply, determine the most accurate Seafood Watch rating: "Best Choice", "Good Alternative", or "Avoid".
3. If the data is insufficient to make a confident rating (e.g., missing country of origin or production method), you MUST state what is missing in the notes and lower the reliability score.
4. If the provided information could correspond to multiple ratings, mention this in the notes and provide the most likely rating.
5. The reliability score should be a percentage (0-100) indicating your confidence in the match. 100% means all necessary Key Data Elements are present for an exact match. A "Certified" rating should have a high reliability score (95-100).
6. If a rating is impossible to determine, use the rating "N/A".
7. For the 'uniqueId' field, provide the specific Seafood Watch Recommendation ID (e.g., '12345') associated with the matched rating. If the rating is 'Certified' or 'N/A', or if a specific ID cannot be determined, use 'N/A'.

Respond ONLY with a single, raw JSON array. Each element in the array must be a JSON object corresponding to an item in the input array, in the same order. The response array must have the exact same number of elements as the input array. Do not add any extra text, explanations, or markdown formatting like \`\`\`json.`;

type AnalysisResult = Pick<SeafoodResultItem, 'uniqueId' | 'rating' | 'reliabilityScore' | 'notes'>;

const BATCH_SIZE = 15; // Process 15 items per API call to reduce request size
const API_DELAY_MS = 6000; // 6-second delay between batches (10 RPM) to stay safely under limits

async function rateBatch(items: SeafoodInputItem[]): Promise<AnalysisResult[]> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const totalRetries = 5;
    let retries = totalRetries;
    let delay = 5000; // Initial retry delay of 5s

    const failedResult: AnalysisResult = {
        uniqueId: "N/A",
        rating: Rating.NA,
        reliabilityScore: 0,
        notes: "An error occurred during analysis.",
    };
    const rateLimitResult: AnalysisResult = {
        uniqueId: "N/A",
        rating: Rating.NA,
        reliabilityScore: 0,
        notes: "Rate limit exceeded. Try a smaller file or wait a minute.",
    }

    while (retries > 0) {
        try {
            const prompt = `Please analyze this batch of seafood items: ${JSON.stringify(items)}`;

            const response = await ai.models.generateContent({
                model: 'gemini-2.5-flash',
                contents: prompt,
                config: {
                systemInstruction: systemInstruction,
                responseMimeType: "application/json",
                responseSchema: responseSchema,
                temperature: 0.1,
                },
            });

            const jsonText = response.text.trim();
            const results: any[] = JSON.parse(jsonText);

            if (!Array.isArray(results) || results.length !== items.length) {
                console.error(`API response mismatch: expected ${items.length} items, got ${results.length}.`);
                throw new Error(`API returned an incorrect number of items for the batch.`);
            }

            // Validate and format results
            return results.map(result => ({
                uniqueId: result.uniqueId || "N/A",
                rating: result.rating || Rating.NA,
                reliabilityScore: result.reliabilityScore || 0,
                notes: result.notes || "No notes provided.",
            }));

        } catch (error) {
            console.error("Error processing batch with Gemini:", error);

            const errorString = JSON.stringify(error);
            if (errorString.includes('429')) {
                retries--;
                if (retries === 0) {
                    // Fill the batch with rate limit errors
                    return items.map(() => rateLimitResult);
                }
                const jitter = Math.random() * 1000;
                console.warn(`Rate limit hit. Retrying in ${Math.round((delay + jitter) / 1000)}s... (${retries} retries left)`);
                await new Promise(resolve => setTimeout(resolve, delay + jitter));
                delay *= 2; // Exponential backoff
            } else {
                // Non-retryable error for the whole batch
                return items.map(() => failedResult);
            }
        }
    }

    // Fallback for when retries are exhausted
    return items.map(() => rateLimitResult);
}

export async function rateSeafoodData(
  data: SeafoodInputItem[],
  onProgress: (processed: number, total: number) => void
): Promise<AnalysisResult[]> {
  const allResults: AnalysisResult[] = [];
  const total = data.length;

  const rateLimitNote = "Rate limit exceeded. Try a smaller file or wait a minute.";
  const processingStoppedNote = "Processing stopped due to API rate limits.";

  for (let i = 0; i < total; i += BATCH_SIZE) {
    const batch = data.slice(i, i + BATCH_SIZE);
    const batchResults = await rateBatch(batch);
    allResults.push(...batchResults);

    const processedCount = allResults.length;
    onProgress(processedCount, total);

    // Circuit Breaker: If the entire batch failed due to rate limiting, stop processing.
    const isRateLimited = batchResults.every(r => r.notes === rateLimitNote);
    if (isRateLimited) {
        console.warn("API rate limit hit. Aborting further processing.");

        const remainingCount = total - processedCount;
        if (remainingCount > 0) {
            const stoppedResult: AnalysisResult = {
                uniqueId: "N/A",
                rating: Rating.NA,
                reliabilityScore: 0,
                notes: processingStoppedNote,
            };
            for (let j = 0; j < remainingCount; j++) {
                allResults.push(stoppedResult);
            }
            // Final progress update to show completion of abortion.
            onProgress(total, total);
        }
        break; // Exit the loop
    }

    // Don't sleep after the last batch
    if (processedCount < total) {
      await new Promise(resolve => setTimeout(resolve, API_DELAY_MS));
    }
  }

  return allResults;
}

export async function updateAnalysisForId(
