export async function getColumnMapping(
  mappableFields: string[],
  fileHeaders: string[]
): Promise<{ mapping: Record<string, string>; isFallback: boolean }> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const properties: Record<string, object> = {};
  mappableFields.forEach(field => {
    properties[field] = {
      type: Type.STRING,
      enum: [...fileHeaders, 'N/A'],
      description: `The best matching column header from the file for the required field '${field}'. Select 'N/A' if no good match is found.`
    };
  });

  const schema = {
    type: Type.OBJECT,
    properties: properties,
    required: mappableFields,
  };

  const systemInstruction = `You are an expert data mapping specialist. Your task is to analyze a list of required data fields and a list of column headers from an uploaded file. For each required field, you must identify the best matching column header from the file's headers. If no suitable match is found for a field, you must map it to 'N/A'. The data is related to seafood sourcing, so be mindful of synonyms (e.g., 'species' vs 'common name', 'origin' vs 'country'). Respond ONLY with a single, raw JSON object that conforms to the provided schema. Do not add any extra text, explanations, or markdown formatting.`;

  const prompt = `Please map these required fields: ${JSON.stringify(mappableFields)} to the available file headers: ${JSON.stringify(fileHeaders)}.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: prompt,
      config: {
        systemInstruction: systemInstruction,
        responseMimeType: "application/json",
        responseSchema: schema,
        temperature: 0.0,
      },
    });

    const jsonText = response.text.trim();
    const mappingResult = JSON.parse(jsonText);

    const isValid = mappableFields.every(field => 
      Object.prototype.hasOwnProperty.call(mappingResult, field) &&
      (fileHeaders.includes(mappingResult[field]) || mappingResult[field] === 'N/A')
    );

    if (isValid) {
      console.log("Successfully mapped columns with AI.");
      return { mapping: mappingResult, isFallback: false };
    } else {
      console.warn("AI mapping result was invalid or incomplete.", mappingResult);
      throw new Error("Invalid mapping structure returned by AI.");
    }

  } catch (error) {
    console.error("AI column mapping failed. Using keyword-based fallback.", error);
    const staticMapping = performStaticMapping(mappableFields, fileHeaders);
    return { mapping: staticMapping, isFallback: true };
  }
}


export async function analyzeSheetLayout(
  sheetPreviews: { sheetName: string; data: (string | number)[][] }[]
): Promise<{ bestSheetName: string; bestHeaderRow: number }> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const schema = {
    type: Type.OBJECT,
    properties: {
      bestSheetName: {
        type: Type.STRING,
        description: "The name of the sheet most likely containing the main dataset.",
      },
      bestHeaderRow: {
        type: Type.NUMBER,
        description: "The 1-based index of the row most likely to be the header row.",
      },
    },
    required: ["bestSheetName", "bestHeaderRow"],
  };

  const systemInstruction = `You are an expert spreadsheet data analyst. Your task is to examine previews from multiple sheets in a spreadsheet file and determine which sheet contains the primary dataset and which row is the header. The data is related to seafood sourcing, so look for columns like 'species', 'common name', 'country', 'origin', 'production method', 'farmed', 'wild', 'certification', 'supplier', etc. The header row is the one that contains these descriptive titles. It is often the first row, but could be preceded by title rows or empty rows. Ignore summary sheets, charts, or instruction sheets. Respond with the sheet name and the 1-based row number of the header.`;

  const prompt = `Analyze the following sheet previews and identify the best sheet and header row:\n\n${JSON.stringify(sheetPreviews)}`;

  const totalRetries = 5;
  let retries = totalRetries;
  let delay = 5000;

  while (retries > 0) {
    try {
      const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash',
        contents: prompt,
        config: {
          systemInstruction: systemInstruction,
          responseMimeType: "application/json",
          responseSchema: schema,
          temperature: 0.0,
        },
      });

      const jsonText = response.text.trim();
      const result = JSON.parse(jsonText);

      if (
        result &&
        typeof result.bestSheetName === 'string' &&
        typeof result.bestHeaderRow === 'number' &&
        sheetPreviews.some(p => p.sheetName === result.bestSheetName) &&
        result.bestHeaderRow > 0
      ) {
        return result; 
      } else {
        throw new Error("Invalid response from AI model.");
      }
    } catch (error) {
      retries--;
      console.error(`Error analyzing sheet layout (retry ${totalRetries - retries} of ${totalRetries}):`, error);
      const errorString = JSON.stringify(error);
      if (retries > 0 && errorString.includes('429')) {
        const jitter = Math.random() * 1000;
        console.warn(`Rate limit hit on analyzeSheetLayout. Retrying in ${Math.round((delay + jitter) / 1000)}s...`);
        await new Promise(resolve => setTimeout(resolve, delay + jitter));
        delay *= 2;
      } else if (retries > 0) {
        await new Promise(resolve => setTimeout(resolve, 500));
      }
    }
  }

  console.warn("All retries failed for analyzeSheetLayout. Falling back to default.");
  return {
    bestSheetName: sheetPreviews[0]?.sheetName || '',
    bestHeaderRow: 1,
  };
}

function performStaticMapping(mappableFields: string[], fileHeaders: string[]): Record<string, string> {
  const mapping: Record<string, string> = {};
  const availableHeaders = [...fileHeaders];

  for (const field of mappableFields) {
    let bestMatch = 'N/A';
    let highestScore = -1;

    const fieldWords = new Set(field.toLowerCase().replace(/[_-]/g, ' ').split(/\s+/).filter(w => w.length > 2));

    for (const header of availableHeaders) {
      if (!header) continue;

      let currentScore = 0;
      const headerLower = header.toLowerCase();

      if (headerLower === field.toLowerCase()) {
        currentScore = 100;
      } else if (headerLower.includes(field.toLowerCase()) || field.toLowerCase().includes(headerLower)) {
        currentScore = 50;
      }

      const headerWords = new Set(headerLower.replace(/[_-]/g, ' ').split(/\s+/).filter(Boolean));
      let sharedWords = 0;
      for (const fWord of fieldWords) {
        if (headerWords.has(fWord)) {
          sharedWords++;
        }
      }
      currentScore += sharedWords * 10;

      if (currentScore > highestScore) {
        highestScore = currentScore;
        bestMatch = header;
      }
    }

    if (highestScore > 10) { 
        mapping[field] = bestMatch;
    } else {
        mapping[field] = 'N/A';
    }
  }

  return mapping;
}

import React, { useState, useCallback, useEffect } from 'react';
import { SeafoodInputItem, SeafoodResultItem, Rating, UploadSummary } from './types';
import { rateSeafoodData, analyzeSheetLayout, updateAnalysisForId } from './services/geminiService';
import { getUploadHistory, saveUploadToHistory } from './services/historyService';
import { performDataAudit, AuditReport } from './services/dataAuditService';
import Header from './components/Header';
import FileUpload from './components/FileUpload';
import ResultsTable from './components/ResultsTable';
import Loader from './components/Loader';
import Dashboard from './components/Dashboard';
import ColumnMapper from './components/ColumnMapper';
import DataPreview from './components/DataPreview';
import ChartsView from './components/ChartsView';
import Modal from './components/Modal';
import DataQualityAudit from './components/DataQualityAudit';

// This declaration is necessary because the library is loaded from a script tag in index.html
declare var XLSX: any;

type View = 'dashboard' | 'analyzer';
type AnalyzerState = 'upload' | 'preview' | 'mapping' | 'audit' | 'loading' | 'results';
type ResultsViewMode = 'table' | 'charts';

const MAPPABLE_FIELDS = [
  'Wild or Farmed',
  'Common name',
  'Scientific name',
  'Source country',
  'Body of water',
  'Production Method',
  'Certification',
  'Supplier',
  'Product Name',
  'Volume',
];

const App: React.FC = () => {
  const [view, setView] = useState<View>('dashboard');
  const [analyzerState, setAnalyzerState] = useState<AnalyzerState>('upload');
  const [results, setResults] = useState<SeafoodResultItem[] | null>(null);
  const [error, setError] = useState<string | null>(null);

  // State for raw data and headers
  const [originalData, setOriginalData] = useState<SeafoodInputItem[] | null>(null);
  const [originalHeaders, setOriginalHeaders] = useState<string[]>([]);
  const [currentFileName, setCurrentFileName] = useState<string>('');

  // State for column mapping and display-optimized results
  const [columnMapping, setColumnMapping] = useState<Record<string, string>>({});
  const [displayResults, setDisplayResults] = useState<any[] | null>(null);
  const [displayHeaders, setDisplayHeaders] = useState<string[]>([]);
  const [visibleColumns, setVisibleColumns] = useState<Set<string>>(new Set());
  const [auditReport, setAuditReport] = useState<AuditReport | null>(null);


  // State for preview step
  const [workbook, setWorkbook] = useState<any>(null); // XLSX workbook object
  const [sheetNames, setSheetNames] = useState<string[]>([]);
  const [selectedSheet, setSelectedSheet] = useState<string>('');
  const [headerRowIndex, setHeaderRowIndex] = useState<number>(1);
  const [previewData, setPreviewData] = useState<(string|number)[][]>([]);
  const [isPreviewLoading, setIsPreviewLoading] = useState<boolean>(false);
  const [previewWarning, setPreviewWarning] = useState<string | null>(null);


  const [uploadHistory, setUploadHistory] = useState<UploadSummary[]>([]);
  const [progress, setProgress] = useState<{ processed: number; total: number } | null>(null);

  // State for results view
  const [resultsViewMode, setResultsViewMode] = useState<ResultsViewMode>('table');
  const [activeFilter, setActiveFilter] = useState<{title: string; data: any[]} | null>(null);
  const [isFilterModalOpen, setIsFilterModalOpen] = useState(false);
  const [modalFilterData, setModalFilterData] = useState<{title: string; data: SeafoodResultItem[]} | null>(null);


  useEffect(() => {
    // Load history on initial mount
    setUploadHistory(getUploadHistory());
  }, []);

  const resetAnalyzerState = () => {
    setResults(null);
    setDisplayResults(null);
    setDisplayHeaders([]);
    setError(null);
    setOriginalData(null);
    setOriginalHeaders([]);
    setCurrentFileName('');
    setProgress(null);
    setWorkbook(null);
    setSheetNames([]);
    setSelectedSheet('');
    setHeaderRowIndex(1);
    setPreviewData([]);
    setColumnMapping({});
    setAuditReport(null);
    setVisibleColumns(new Set());
    setResultsViewMode('table');
    setActiveFilter(null);
    setIsFilterModalOpen(false);
    setModalFilterData(null);
    setAnalyzerState('upload');
    setIsPreviewLoading(false);
    setPreviewWarning(null);
  };

  const generatePreviewData = (worksheet: any) => {
    const previewJson: (string|number)[][] = XLSX.utils.sheet_to_json(worksheet, { header: 1, defval: '', raw: false, blankrows: false });
    setPreviewData(previewJson.slice(0, 15)); // Preview first 15 rows
  };

  const handleProcessFile = useCallback(async (file: File) => {
    resetAnalyzerState();
    setAnalyzerState('preview');
    setIsPreviewLoading(true);

    const reader = new FileReader();
    reader.onload = async (e) => {
      try {
        const data = e.target?.result;
        if (!data) throw new Error("File data could not be read.");

        let wb: any;
        try {
          wb = XLSX.read(data, { type: 'binary', cellNF: false, cellText: false });
        } catch (parseError) {
          console.error("File parsing error:", parseError);
          throw new Error("Could not parse file. Please ensure it is a valid, uncorrupted XLSX or CSV file.");
        }

        const names = wb.SheetNames;
        if (names.length === 0) {
          throw new Error("The uploaded file is empty or contains no sheets.");
        }

        setWorkbook(wb);
        setSheetNames(names);
        setCurrentFileName(file.name);

        let bestSheetName = names[0];
        let bestHeaderRow = 1;

        try {
          const sheetPreviews = names.map(name => {
            const ws = wb.Sheets[name];
            const sheetData = XLSX.utils.sheet_to_json(ws, { header: 1, defval: '', raw: false, blankrows: false }).slice(0, 15);
            return { sheetName: name, data: sheetData };
          });

          const layout = await analyzeSheetLayout(sheetPreviews);
          bestSheetName = layout.bestSheetName;
          bestHeaderRow = layout.bestHeaderRow;
        } catch (aiError) {
          console.warn("AI sheet analysis failed, falling back to default.", aiError);
          setPreviewWarning("AI analysis for sheet layout failed. We've selected the first sheet and header row as a default. Please verify the selections are correct.");
        }

        setSelectedSheet(bestSheetName);
        setHeaderRowIndex(bestHeaderRow);
        generatePreviewData(wb.Sheets[bestSheetName]);

      } catch (err: any) {
        console.error(err);
        setError(`Error processing file: ${err.message}`);
        setAnalyzerState('upload');
      } finally {
        setIsPreviewLoading(false);
      }
    };
    reader.onerror = () => {
      setError('There was an error reading the file. It may be too large or corrupted.');
      setAnalyzerState('upload');
      setIsPreviewLoading(false);
    }
    reader.readAsBinaryString(file);
  }, []);

  const handleSheetChange = (sheetName: string) => {
    if (workbook) {
      setSelectedSheet(sheetName);
      generatePreviewData(workbook.Sheets[sheetName]);
    }
  };

  const handleHeaderRowChange = (newRowIndex: number) => {
    setHeaderRowIndex(newRowIndex);
  };

  const handleConfirmPreview = useCallback(() => {
    setError(null);
    if (!workbook || !selectedSheet) {
        setError("Workbook data is missing. Please re-upload.");
        setAnalyzerState('upload');
        return;
    }

    try {
        const worksheet = workbook.Sheets[selectedSheet];
        const dataAsArray: any[][] = XLSX.utils.sheet_to_json(worksheet, { header: 1, defval: '', blankrows: false });

        if (dataAsArray.length < headerRowIndex) {
            throw new Error(`Header row ${headerRowIndex} does not exist in the data.`);
        }

        const rawHeaders: string[] = dataAsArray[headerRowIndex - 1].map(header => String(header).trim());

        const headers: string[] = [];
        const counts: Record<string, number> = {};

        for (const header of rawHeaders) {
            if (!header) {
                headers.push('');
                continue;
            }

            counts[header] = (counts[header] || 0) + 1;

            if (counts[header] > 1) {
                let newHeader = `${header} (${counts[header]})`;
                while (rawHeaders.includes(newHeader) || headers.includes(newHeader)) {
                    counts[header]++;
                    newHeader = `${header} (${counts[header]})`;
                }
                headers.push(newHeader);
            } else {
                headers.push(header);
            }
        }

        const jsonData = dataAsArray.slice(headerRowIndex).map(row => {
            const rowObject: SeafoodInputItem = {};
            headers.forEach((header, index) => {
                if(header) {
                    rowObject[header] = row[index];
                }
            });
            return rowObject;
        }).filter(obj => Object.keys(obj).length > 0);

        if (jsonData.length === 0) {
          throw new Error("The selected sheet and header row result in no data to process.");
        }

        setOriginalData(jsonData);
        setOriginalHeaders(headers.filter(h => h));
        setAnalyzerState('mapping');

    } catch(err: any) {
        setError(`Error processing sheet: ${err.message}`);
    }
  }, [workbook, selectedSheet, headerRowIndex]);

  const handleConfirmMapping = useCallback((mapping: Record<string, string>) => {
    if (!originalData) {
        setError("Original data missing.");
        setAnalyzerState('upload');
        return;
    }
    setColumnMapping(mapping);

    // Perform Audit
    const report = performDataAudit(originalData, mapping);
    setAuditReport(report);
    setAnalyzerState('audit');

  }, [originalData]);

  const handleStartAnalysis = useCallback(async () => {
    if (!originalData) return;

    setAnalyzerState('loading');
    setError(null);

    try {
        // Filter out rows that don't have a Common Name
        const commonNameHeader = columnMapping['Common name'];
        let dataToProcess = originalData;

        if (commonNameHeader && commonNameHeader !== 'N/A') {
            dataToProcess = originalData.filter(row => {
                const val = row[commonNameHeader];
                return val !== undefined && val !== null && String(val).trim() !== '';
            });
        }

        setProgress({ processed: 0, total: dataToProcess.length });

        if (dataToProcess.length === 0) {
             throw new Error("No valid rows found to process. Please ensure your data has values in the 'Common name' column.");
        }

        const transformedData = dataToProcess.map(row => {
            const newRow: { [key: string]: string | number } = {};
            for (const mappableField of MAPPABLE_FIELDS) {
                const userColumnName = columnMapping[mappableField];
                if (userColumnName && userColumnName !== 'N/A' && row[userColumnName] !== undefined) {
                    newRow[mappableField] = row[userColumnName];
                }
            }
            return newRow;
        });

        const handleProgressUpdate = (processed: number, total: number) => {
          setProgress({ processed, total });
        };

        const analysisResults = await rateSeafoodData(transformedData, handleProgressUpdate);

        const finalResults = dataToProcess.map((originalItem, index) => {
            const analysisPart = analysisResults[index];

            return {
                ...originalItem,
                uniqueId: analysisPart.uniqueId,
                matchedKDEs: analysisPart.matchedKDEs, // Use the official KDEs returned by AI
                rating: analysisPart.rating,
                reliabilityScore: analysisPart.reliabilityScore,
                notes: analysisPart.notes,
            };
        });

        setResults(finalResults);

        const mappedHeaders = Object.values(columnMapping).filter(h => h && h !== 'N/A') as string[];
        const defaultVisible = new Set<string>([
            ...mappedHeaders,
            'uniqueId', 
            'rating', 
            'reliabilityScore', 
            'notes'
        ]);

        setDisplayResults(finalResults);
        setDisplayHeaders(originalHeaders);
        setVisibleColumns(defaultVisible);

        const matchedCount = finalResults.filter(r => r.rating !== Rating.NA).length;
        const matchPercentage = finalResults.length > 0 ? (matchedCount / finalResults.length) * 100 : 0;
        const totalReliability = finalResults.reduce((acc, r) => acc + r.reliabilityScore, 0);
        const averageReliability = finalResults.length > 0 ? totalReliability / finalResults.length : 0;
        const ratingDistribution = finalResults.reduce<{[key in Rating]?: number}>((acc, item) => {
            acc[item.rating] = (acc[item.rating] || 0) + 1;
            return acc;
        }, {});

        const noteCounts = finalResults.reduce((acc, item) => {
          acc[item.notes] = (acc[item.notes] || 0) + 1;
          return acc;
        }, {} as { [key: string]: number });
        const commonIssues = Object.entries(noteCounts)
          .sort(([, countA], [, countB]) => (countB as number) - (countA as number))
          .slice(0, 5)
          .map(([issue, count]) => ({ issue, count: count as number }));
        const newHistory = saveUploadToHistory({
            fileName: currentFileName, rowCount: finalResults.length, matchPercentage,
            averageReliability, ratingDistribution, commonIssues,
        });
        setUploadHistory(newHistory);
        setAnalyzerState('results');

    } catch (err: any) {
        console.error(err);
        setError(`An error occurred during analysis: ${err.message}`);
        setAnalyzerState('mapping');
    }
  }, [originalData, currentFileName, originalHeaders, columnMapping]);

  const handleUpdateResult = useCallback(async (index: number, newUniqueId: string) => {
     if (!results || !results[index]) return;

     // Optimistic update to show loading state
     const updatedResults = [...results];
     updatedResults[index] = { ...updatedResults[index], isUpdating: true, uniqueId: newUniqueId };
     setResults(updatedResults);
     setDisplayResults(updatedResults);

     try {
         const originalItem = updatedResults[index];
         const updatedAnalysis = await updateAnalysisForId(originalItem, newUniqueId);

         const finalResults = [...results];
         finalResults[index] = {
             ...originalItem,
             ...updatedAnalysis,
             isUpdating: false
         };

         setResults(finalResults);
         setDisplayResults(finalResults);

     } catch (err) {
         console.error("Failed to update result:", err);
         // Revert on failure
         const revertedResults = [...results];
         revertedResults[index] = { ...revertedResults[index], isUpdating: false };
         setResults(revertedResults);
         setDisplayResults(revertedResults);
         setError("Failed to update the record. Please try again.");
     }
  }, [results]);

  const handleExport = useCallback(() => {
    if (!results || originalHeaders.length === 0) return;
    const headers = [...originalHeaders, 'Unique ID', 'Matched KDEs', 'Rating', 'Reliability Score', 'Notes'];
    const escapeCsv = (val: any): string => {
        if (val === undefined || val === null) return '';
        const str = String(val);
        if (str.includes(',') || str.includes('"') || str.includes('\n')) {
            return `"${str.replace(/"/g, '""')}"`;
        }
        return str;
    };
    const csvContent = [
        headers.join(','),
        ...results.map(row => {
            const originalValues = originalHeaders.map(header => escapeCsv(row[header]));
            const analysisValues = [
                escapeCsv(row.uniqueId), 
                escapeCsv(row.matchedKDEs),
                escapeCsv(row.rating), 
                escapeCsv(row.reliabilityScore), 
                escapeCsv(row.notes)
            ];
            return [...originalValues, ...analysisValues].join(',');
        })
    ].join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    if (link.href) URL.revokeObjectURL(link.href);
    const url = URL.createObjectURL(blob);
    link.href = url;
    link.setAttribute('download', `${currentFileName.replace(/\.[^/.]+$/, "")}_analyzed.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  }, [results, originalHeaders, currentFileName]);

  const handleChartSegmentClick = (title: string, data: SeafoodResultItem[]) => {
    setModalFilterData({ title, data });
    setIsFilterModalOpen(true);
  };
  const handleConfirmFilter = () => {
    if (modalFilterData) {
      setActiveFilter({ title: modalFilterData.title, data: modalFilterData.data });
      setResultsViewMode('table');
    }
    setIsFilterModalOpen(false);
  };
  const handleClearFilter = () => setActiveFilter(null);
  const handleCancelFilter = () => setIsFilterModalOpen(false);
  const handleVisibleColumnsChange = (newVisible: Set<string>) => {
    setVisibleColumns(newVisible);
  };
  const handleCancel = () => resetAnalyzerState();
  const handleReturnToPreview = () => { setOriginalData(null); setOriginalHeaders([]); setAnalyzerState('preview'); };
  const handleReturnToMapping = () => { setAnalyzerState('mapping'); }; // New helper for Audit back button
  const handleAnalyzeNew = () => { resetAnalyzerState(); setView('analyzer'); };
  const handleReturnToDashboard = () => { resetAnalyzerState(); setView('dashboard'); };

  const renderContent = () => {
    if (view === 'dashboard') {
      return (
          <div className="animate-fade-in-up">
              <Dashboard history={uploadHistory} onAnalyzeNew={handleAnalyzeNew} />
          </div>
      );
    }

    // Analyzer Views Wrapper
    return (
      <div className="animate-fade-in-up" key={analyzerState}>
        {error && (
            <div className="bg-red-100 border border-red-400 text-red-700 px-4 py-3 rounded-lg relative my-6 max-w-4xl mx-auto" role="alert">
            <strong className="font-bold">Error:</strong><span className="block sm:inline ml-2">{error}</span>
            </div>
        )}
        {analyzerState === 'upload' && <FileUpload onProcessFile={handleProcessFile} isLoading={false} />}
        {analyzerState === 'preview' && <DataPreview isAnalyzing={isPreviewLoading} sheetNames={sheetNames} selectedSheet={selectedSheet} onSheetChange={handleSheetChange} headerRowIndex={headerRowIndex} onHeaderRowChange={handleHeaderRowChange} previewData={previewData} onConfirm={handleConfirmPreview} onCancel={handleCancel} warning={previewWarning}/>}
        {analyzerState === 'mapping' && originalHeaders.length > 0 && <ColumnMapper fileHeaders={originalHeaders} mappableFields={MAPPABLE_FIELDS} onConfirm={handleConfirmMapping} onCancel={handleReturnToPreview}/>}
        {analyzerState === 'audit' && auditReport && <DataQualityAudit report={auditReport} onConfirm={handleStartAnalysis} onBack={handleReturnToMapping} />}
        {analyzerState === 'loading' && <Loader progress={progress} />}
        {analyzerState === 'results' && results && displayResults && (
          <div className="flex flex-col items-center space-y-6">
            <div 
              className="flex justify-center p-1 bg-gray-200 rounded-lg"
              role="tablist"
              aria-label="Result view modes"
            >
              <button 
                id="tab-table"
                role="tab"
                aria-selected={resultsViewMode === 'table'}
                aria-controls="tabpanel-table"
                onClick={() => setResultsViewMode('table')} 
                className={`px-4 py-2 text-sm font-semibold rounded-md transition-colors ${resultsViewMode === 'table' ? 'bg-white shadow text-gray-800' : 'text-gray-600'}`}>
                  Table
              </button>
              <button 
                id="tab-charts"
                role="tab"
                aria-selected={resultsViewMode === 'charts'}
                aria-controls="tabpanel-charts"
                onClick={() => setResultsViewMode('charts')} 
                className={`px-4 py-2 text-sm font-semibold rounded-md transition-colors ${resultsViewMode === 'charts' ? 'bg-white shadow text-gray-800' : 'text-gray-600'}`}>
                  Charts
              </button>
            </div>

            <div className="w-full max-w-7xl">
              {resultsViewMode === 'table' ? (
                 <div id="tabpanel-table" role="tabpanel" aria-labelledby="tab-table">
                    <ResultsTable 
                        results={activeFilter ? activeFilter.data : displayResults} 
                        originalHeaders={displayHeaders} 
                        onExport={handleExport}
                        filterTitle={activeFilter?.title}
                        onClearFilter={handleClearFilter}
                        visibleColumns={visibleColumns}
                        onVisibleColumnsChange={handleVisibleColumnsChange}
                        onUpdateResult={handleUpdateResult}
                    />
                 </div>
              ) : (
                <div id="tabpanel-charts" role="tabpanel" aria-labelledby="tab-charts">
                    <ChartsView 
                        results={results} 
                        columnMapping={columnMapping} 
                        onSegmentClick={handleChartSegmentClick}
                    />
                </div>
              )}
            </div>

            <button onClick={handleReturnToDashboard} className="px-6 py-2 font-semibold text-white bg-[#00629B] rounded-md hover:bg-[#00497b] focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-[#00629B] transition-colors duration-200">Back to Dashboard</button>
          </div>
        )}
         <Modal 
            isOpen={isFilterModalOpen} 
            onClose={handleCancelFilter} 
            onConfirm={handleConfirmFilter}
            title="View Filtered Data"
         >
            <p>Would you like to see the {modalFilterData?.data.length} items for "{modalFilterData?.title}" in the data table?</p>
         </Modal>
      </div>
    );
  };

  return (
    <div className="min-h-screen bg-gray-50 text-gray-800 font-sans">
      <Header />
      <main className="container mx-auto p-4 sm:p-6 md:p-8">
        {renderContent()}
      </main>
      <footer className="text-center py-4 text-gray-500 text-sm">
        <p>&copy; {new Date().getFullYear()} Monterey Bay Aquarium Seafood Watch Program</p>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useCallback, useRef, useEffect, useMemo } from 'react';
import { SeafoodResultItem } from '../types';
import RatingBadge from './RatingBadge';
import ColumnToggler from './ColumnToggler';

interface ResultsTableProps {
  results: any[];
  originalHeaders: string[];
  onExport: () => void;
  filterTitle?: string;
  onClearFilter?: () => void;
  visibleColumns: Set<string>;
  onVisibleColumnsChange: (newVisible: Set<string>) => void;
  onUpdateResult?: (index: number, newUniqueId: string) => Promise<void>;
}

type SortDirection = 'ascending' | 'descending';

const SortIcon: React.FC<{ direction: SortDirection | null }> = ({ direction }) => {
    if (!direction) return null;
    return (
      <svg
        className="w-4 h-4 ml-1 inline-block text-gray-500 flex-shrink-0"
        aria-hidden="true"
        fill="currentColor"
        viewBox="0 0 20 20"
        xmlns="http://www.w3.org/2000/svg"
      >
        {direction === 'descending' ? (
          <path
            fillRule="evenodd"
            d="M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z"
            clipRule="evenodd"
          />
        ) : (
          <path
            fillRule="evenodd"
            d="M14.707 12.707a1 1 0 01-1.414 0L10 9.414l-3.293 3.293a1 1 0 01-1.414-1.414l4-4a1 1 0 011.414 0l4 4a1 1 0 010 1.414z"
            clipRule="evenodd"
          />
        )}
      </svg>
    );
};


const ResultsTable: React.FC<ResultsTableProps> = ({ 
  results, 
  originalHeaders, 
  onExport, 
  filterTitle, 
  onClearFilter,
  visibleColumns, 
  onVisibleColumnsChange,
  onUpdateResult
}) => {
  const [columnWidths, setColumnWidths] = useState<Record<string, number>>({});
  const isResizing = useRef<string | null>(null);
  const [sortConfig, setSortConfig] = useState<{ key: string; direction: SortDirection } | null>(null);
  const [searchTerm, setSearchTerm] = useState('');

  // Tooltip State
  const [tooltip, setTooltip] = useState<{ content: string; x: number; y: number } | null>(null);

  // Edit State
  const [editingId, setEditingId] = useState<{ index: number; value: string } | null>(null);


  // Refs for synced scrolling
  const tableContainerRef = useRef<HTMLDivElement>(null);
  const topScrollRef = useRef<HTMLDivElement>(null);
  const [scrollWidth, setScrollWidth] = useState(0);

  const sortedResults = useMemo(() => {
    // Add original index to items to track them after sorting
    const itemsWithIndex = results.map((item, index) => ({ ...item, _originalIndex: index }));

    if (!sortConfig) {
      return itemsWithIndex;
    }
    const sortableItems = [...itemsWithIndex];
    sortableItems.sort((a, b) => {
        const aVal = a[sortConfig.key];
        const bVal = b[sortConfig.key];

        if (aVal == null) return 1;
        if (bVal == null) return -1;

        if (typeof aVal === 'number' && typeof bVal === 'number') {
            return sortConfig.direction === 'ascending' ? aVal - bVal : bVal - aVal;
        }

        const aStr = String(aVal);
        const bStr = String(bVal);
        const comparison = aStr.localeCompare(bStr, undefined, { numeric: true, sensitivity: 'base' });

        return sortConfig.direction === 'ascending' ? comparison : -comparison;
      });

    return sortableItems;
  }, [results, sortConfig]);

  const filteredAndSortedResults = useMemo(() => {
    if (!searchTerm) {
      return sortedResults;
    }
    const lowercasedFilter = searchTerm.toLowerCase();
    return sortedResults.filter(item => {
       const { _originalIndex, isUpdating, ...searchableItem } = item;
      return Object.values(searchableItem).some(value =>
        String(value).toLowerCase().includes(lowercasedFilter)
      );
    });
  }, [sortedResults, searchTerm]);

  // Sync scrollbars
  useEffect(() => {
    const syncScroll = (source: 'top' | 'bottom') => {
      const top = topScrollRef.current;
      const bottom = tableContainerRef.current;
      if (!top || !bottom) return;

      if (source === 'top') {
        bottom.scrollLeft = top.scrollLeft;
      } else {
        top.scrollLeft = bottom.scrollLeft;
      }
    };

    const top = topScrollRef.current;
    const bottom = tableContainerRef.current;

    if (top && bottom) {
      const handleTopScroll = () => syncScroll('top');
      const handleBottomScroll = () => syncScroll('bottom');

      top.addEventListener('scroll', handleTopScroll);
      bottom.addEventListener('scroll', handleBottomScroll);

      return () => {
        top.removeEventListener('scroll', handleTopScroll);
        bottom.removeEventListener('scroll', handleBottomScroll);
      };
    }
  }, []);

  // Update scroll width when data or columns change
  useEffect(() => {
    if (tableContainerRef.current) {
      setScrollWidth(tableContainerRef.current.scrollWidth);
    }
  }, [visibleColumns, filteredAndSortedResults, columnWidths]);

  const requestSort = (key: string) => {
    let direction: SortDirection = 'ascending';
    if (sortConfig && sortConfig.key === key && sortConfig.direction === 'ascending') {
      direction = 'descending';
    }
    setSortConfig({ key, direction });
  };

  const handleMouseEnter = (e: React.MouseEvent, content: string) => {
    if (!content) return;
    setTooltip({ 
        content, 
        x: e.clientX, 
        y: e.clientY 
    });
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (tooltip) {
        // Tighter positioning: +5 instead of +15
        setTooltip(prev => prev ? { ...prev, x: e.clientX, y: e.clientY } : null);
    }
  };

  const handleMouseLeave = () => {
    setTooltip(null);
  };

   // Editing handlers
   const startEditing = (index: number, value: string) => {
    setEditingId({ index, value });
};

const handleEditChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (editingId) {
        setEditingId({ ...editingId, value: e.target.value });
    }
};

const submitEdit = async () => {
    if (editingId && onUpdateResult) {
        const { index, value } = editingId;
        const originalItem = results[index];

        if (originalItem.uniqueId !== value) {
             await onUpdateResult(index, value);
        }
    }
    setEditingId(null);
};

const handleEditKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
        submitEdit();
    } else if (e.key === 'Escape') {
        setEditingId(null);
    }
};


  if (!results.length) {
    return <p className="text-center text-gray-500 my-8">
        {filterTitle ? `No data matches the filter "${filterTitle}".` : 'No data to display.'}
    </p>;
  }

  const addedHeaders = [
    { key: 'uniqueId', title: 'Unique ID' },
    // Matched KDEs removed as column
    { key: 'rating', title: 'Rating' },
    { key: 'reliabilityScore', title: 'Reliability' },
    { key: 'notes', title: 'Notes' },
  ];

  const allColumns = [
    ...originalHeaders.map(h => ({ key: h, title: h })),
    ...addedHeaders.map(h => ({ key: h.key, title: h.title }))
  ];

  const visibleOriginalHeaders = originalHeaders.filter(h => visibleColumns.has(h));
  const visibleAddedHeaders = addedHeaders.filter(h => visibleColumns.has(h.key));

  useEffect(() => {
    setColumnWidths(prevWidths => {
        const newWidths = { ...prevWidths };
        visibleOriginalHeaders.forEach(h => {
            if (!newWidths[h]) newWidths[h] = 100; // Reduced from 120
        });
        visibleAddedHeaders.forEach(h => {
            if (!newWidths[h.key]) {
                if (h.key === 'notes') newWidths[h.key] = 400; // Increased to 400
                else if (h.key === 'reliabilityScore') newWidths[h.key] = 90; // Reduced from 140
                else if (h.key === 'uniqueId') newWidths[h.key] = 90;
                else newWidths[h.key] = 90; // Reduced from 110
            }
        });
        return newWidths;
    });
  }, [visibleOriginalHeaders, visibleAddedHeaders]);

  const handleMouseDown = useCallback((e: React.MouseEvent<HTMLDivElement>, headerKey: string) => {
    isResizing.current = headerKey;
    const startX = e.clientX;
    const startWidth = columnWidths[headerKey] || 0;

    const handleMouseMove = (moveEvent: MouseEvent) => {
      if (isResizing.current !== headerKey) return;
      const width = startWidth + (moveEvent.clientX - startX);
      if (width > 50) { // Min width
        setColumnWidths(prev => ({ ...prev, [headerKey]: width }));
      }
    };

    const handleMouseUp = () => {
      isResizing.current = null;
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseup', handleMouseUp);
      document.body.style.cursor = 'default';
      document.body.style.userSelect = 'auto';
    };

    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('mouseup', handleMouseUp);
    e.preventDefault();
    document.body.style.cursor = 'col-resize';
    document.body.style.userSelect = 'none';
  }, [columnWidths]);

  const renderUniqueId = (item: any, originalIndex: number) => {
    if (item.isUpdating) {
        return (
           <div className="flex items-center space-x-2">
               <div className="w-3 h-3 border-2 border-blue-600 border-dashed rounded-full animate-spin"></div>
               <span className="text-xs text-gray-500">Updating...</span>
           </div>
        );
    }

    if (editingId && editingId.index === originalIndex) {
        return (
            <input
              type="text"
              value={editingId.value}
              onChange={handleEditChange}
              onBlur={submitEdit}
              onKeyDown={handleEditKeyDown}
              autoFocus
              className="w-full text-xs border-b border-blue-500 focus:outline-none bg-transparent"
            />
        );
    }

    return (
      <span 
          className="font-mono text-xs text-blue-700 cursor-pointer hover:bg-blue-100 px-1 rounded transition-colors"
          title="Click to edit ID manually"
          onClick={() => startEditing(originalIndex, item.uniqueId)}
          onMouseEnter={(e) => handleMouseEnter(e, item.matchedKDEs)}
          onMouseMove={handleMouseMove}
          onMouseLeave={handleMouseLeave}
      >
          {item.uniqueId}
          <span className="sr-only">Click to edit</span>
      </span>
    );
  };

  const addedColumnRenderers: Record<string, (item: any, originalIndex: number) => React.ReactNode> = {
    uniqueId: (item, originalIndex) => renderUniqueId(item, originalIndex),
    rating: (item) => <RatingBadge rating={item.rating} />,
    reliabilityScore: (item) => (
        <div className="flex items-center" aria-label={`Reliability: ${item.reliabilityScore}%`}>
            <div role="progressbar" aria-valuenow={item.reliabilityScore} aria-valuemin={0} aria-valuemax={100} className="w-16 bg-gray-200 rounded-full h-2.5">
                <div className="bg-blue-600 h-2.5 rounded-full" style={{ width: `${item.reliabilityScore}%` }}></div>
            </div>
            <span className="ml-2 font-medium text-xs">{item.reliabilityScore}%</span>
        </div>
    ),
    notes: (item) => <span className="block leading-tight">{item.notes}</span>,
  };


  return (
    <div className="w-full bg-white p-6 md:p-8 rounded-lg shadow-lg border border-gray-200 relative">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center mb-6 gap-4">
        <div className="flex-grow">
          <h2 id="results-heading" className="text-2xl font-bold text-gray-800">Analysis Results</h2>
          <p className="text-sm text-gray-500 mt-1">Tip: Click a Unique ID to manually correct it.</p>
          {filterTitle && (
            <div className="flex items-center gap-3 mt-2">
                <p className="text-sm text-gray-600">
                    Showing data for: <span className="font-semibold bg-blue-100 text-blue-800 px-2 py-1 rounded-md">{filterTitle}</span>
                </p>
                <button 
                    onClick={onClearFilter}
                    className="text-sm text-blue-600 hover:underline"
                >
                    Clear Filter
                </button>
            </div>
          )}
          <div className="mt-4 flex items-center gap-4">
            <div className="relative flex-grow max-w-sm">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 text-gray-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
                    </svg>
                </div>
                <input
                    type="search"
                    id="table-search"
                    aria-label="Search results"
                    placeholder={`Search in ${results.length} results...`}
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    className="block w-full pl-10 pr-3 py-2 border border-gray-300 rounded-md leading-5 bg-white placeholder-gray-500 focus:outline-none focus:placeholder-gray-400 focus:ring-1 focus:ring-blue-500 focus:border-blue-500 sm:text-sm"
                />
            </div>
            {searchTerm && (
                <button
                    onClick={() => setSearchTerm('')}
                    className="text-sm text-blue-600 hover:underline"
                >
                    Clear Search
                </button>
            )}
          </div>
        </div>
        <div className="flex items-center gap-4 flex-shrink-0">
          <ColumnToggler 
            allColumns={allColumns}
            visibleColumns={visibleColumns}
            onVisibilityChange={onVisibleColumnsChange}
          />
          <button
            onClick={onExport}
            className="flex items-center gap-2 px-4 py-2 text-sm font-semibold text-white bg-green-600 rounded-md hover:bg-green-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-green-600 transition-colors duration-200"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2">
                <path strokeLinecap="round" strokeLinejoin="round" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" />
            </svg>
            Export Full Dataset (CSV)
          </button>
        </div>
      </div>

      {/* Top Scrollbar */}
      <div 
        ref={topScrollRef}
        className="overflow-x-auto w-full mb-1"
        style={{ height: '12px' }}
      >
        <div style={{ width: scrollWidth, height: '1px' }}></div>
      </div>

      <div 
        ref={tableContainerRef}
        className="overflow-x-auto max-h-[70vh]" // Constrain height for sticky header
      >
        {filteredAndSortedResults.length > 0 ? (
            <table className="min-w-full divide-y divide-gray-200 table-fixed" aria-labelledby="results-heading">
            {/* Sticky Header */}
            <thead className="bg-gray-100 sticky top-0 z-10 shadow-sm">
                <tr>
                {visibleOriginalHeaders.map((header) => (
                    <th 
                        key={header} 
                        scope="col" 
                        className="px-2 py-2 text-left text-xs font-bold text-gray-600 uppercase tracking-wider relative group bg-gray-100 align-bottom border-b border-gray-200"
                        style={{ width: columnWidths[header] ? `${columnWidths[header]}px` : undefined }}
                        aria-sort={sortConfig?.key === header ? sortConfig.direction : 'none'}
                    >
                    <button onClick={() => requestSort(header)} className="flex items-end w-full h-full">
                        <span className="whitespace-normal break-words leading-tight">{header}</span>
                        <SortIcon direction={sortConfig?.key === header ? sortConfig.direction : null} />
                    </button>
                    <div
                        onMouseDown={(e) => handleMouseDown(e, header)}
                        aria-hidden="true"
                        className="absolute top-0 right-0 h-full w-2 cursor-col-resize hover:bg-blue-200"
                    />
                    </th>
                ))}
                {visibleAddedHeaders.map((header) => (
                    <th 
                        key={header.key} 
                        scope="col" 
                        className="px-2 py-2 text-left text-xs font-bold text-blue-800 bg-blue-100 uppercase tracking-wider relative group align-bottom border-b border-blue-200"
                        style={{ width: columnWidths[header.key] ? `${columnWidths[header.key]}px` : undefined }}
                        aria-sort={sortConfig?.key === header.key ? sortConfig.direction : 'none'}
                    >
                    <button onClick={() => requestSort(header.key)} className="flex items-end w-full h-full">
                        <span className="whitespace-normal break-words leading-tight">{header.title}</span>
                        <SortIcon direction={sortConfig?.key === header.key ? sortConfig.direction : null} />
                    </button>
                    <div
                        onMouseDown={(e) => handleMouseDown(e, header.key)}
                        aria-hidden="true"
                        className="absolute top-0 right-0 h-full w-2 cursor-col-resize hover:bg-blue-300"
                    />
                    </th>
                ))}
                </tr>
            </thead>
            <tbody className="bg-white divide-y divide-gray-200">
                {filteredAndSortedResults.map((item, index) => (
                <tr key={index} className="hover:bg-gray-50">
                    {visibleOriginalHeaders.map((header) => (
                    <td key={`${header}-${index}`} className="px-2 py-2 text-xs text-gray-700 break-words align-top leading-tight">
                        {item[header]}
                    </td>
                    ))}
                    {visibleAddedHeaders.map((header) => (
                        <td key={`${header.key}-${index}`} className="px-2 py-2 text-xs text-gray-700 bg-blue-50/50 align-top leading-tight">
                            {addedColumnRenderers[header.key](item, item._originalIndex)}
                        </td>
                    ))}
                </tr>
                ))}
            </tbody>
            </table>
        ) : (
            <p className="text-center text-gray-500 my-8 py-4">
                No results found for your search: "{searchTerm}".
            </p>
        )}
      </div>

      {/* Floating Tooltip Portal */}
      {tooltip && (
          <div 
            className="fixed z-50 px-3 py-2 bg-gray-900 text-white text-xs rounded shadow-lg max-w-xs break-words pointer-events-none"
            style={{ 
                left: Math.min(window.innerWidth - 300, tooltip.x + 2), // Slight offset 2px
                top: tooltip.y + 2,
                transform: 'translateZ(0)'
