export async function getColumnMapping(
  mappableFields: string[],
  fileHeaders: string[]
): Promise<{ mapping: Record<string, string>; isFallback: boolean }> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const properties: Record<string, object> = {};
  mappableFields.forEach(field => {
    properties[field] = {
      type: Type.STRING,
      enum: [...fileHeaders, 'N/A'],
      description: `The best matching column header from the file for the required field '${field}'. Select 'N/A' if no good match is found.`
    };
  });

  const schema = {
    type: Type.OBJECT,
    properties: properties,
    required: mappableFields,
  };

  const systemInstruction = `You are an expert data mapping specialist. Your task is to analyze a list of required data fields and a list of column headers from an uploaded file. For each required field, you must identify the best matching column header from the file's headers. If no suitable match is found for a field, you must map it to 'N/A'. The data is related to seafood sourcing, so be mindful of synonyms (e.g., 'species' vs 'common name', 'origin' vs 'country'). Respond ONLY with a single, raw JSON object that conforms to the provided schema. Do not add any extra text, explanations, or markdown formatting.`;

  const prompt = `Please map these required fields: ${JSON.stringify(mappableFields)} to the available file headers: ${JSON.stringify(fileHeaders)}.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: prompt,
      config: {
        systemInstruction: systemInstruction,
        responseMimeType: "application/json",
        responseSchema: schema,
        temperature: 0.0,
      },
    });

    const jsonText = response.text.trim();
    const mappingResult = JSON.parse(jsonText);

    const isValid = mappableFields.every(field => 
      Object.prototype.hasOwnProperty.call(mappingResult, field) &&
      (fileHeaders.includes(mappingResult[field]) || mappingResult[field] === 'N/A')
    );

    if (isValid) {
      console.log("Successfully mapped columns with AI.");
      return { mapping: mappingResult, isFallback: false };
    } else {
      console.warn("AI mapping result was invalid or incomplete.", mappingResult);
      throw new Error("Invalid mapping structure returned by AI.");
    }

  } catch (error) {
    console.error("AI column mapping failed. Using keyword-based fallback.", error);
    const staticMapping = performStaticMapping(mappableFields, fileHeaders);
    return { mapping: staticMapping, isFallback: true };
  }
}


export async function analyzeSheetLayout(
  sheetPreviews: { sheetName: string; data: (string | number)[][] }[]
): Promise<{ bestSheetName: string; bestHeaderRow: number }> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const schema = {
    type: Type.OBJECT,
    properties: {
      bestSheetName: {
        type: Type.STRING,
        description: "The name of the sheet most likely containing the main dataset.",
      },
      bestHeaderRow: {
        type: Type.NUMBER,
        description: "The 1-based index of the row most likely to be the header row.",
      },
    },
    required: ["bestSheetName", "bestHeaderRow"],
  };

  const systemInstruction = `You are an expert spreadsheet data analyst. Your task is to examine previews from multiple sheets in a spreadsheet file and determine which sheet contains the primary dataset and which row is the header. The data is related to seafood sourcing, so look for columns like 'species', 'common name', 'country', 'origin', 'production method', 'farmed', 'wild', 'certification', 'supplier', etc. The header row is the one that contains these descriptive titles. It is often the first row, but could be preceded by title rows or empty rows. Ignore summary sheets, charts, or instruction sheets. Respond with the sheet name and the 1-based row number of the header.`;

  const prompt = `Analyze the following sheet previews and identify the best sheet and header row:\n\n${JSON.stringify(sheetPreviews)}`;

  const totalRetries = 5;
  let retries = totalRetries;
  let delay = 5000;

  while (retries > 0) {
    try {
      const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash',
        contents: prompt,
        config: {
          systemInstruction: systemInstruction,
          responseMimeType: "application/json",
          responseSchema: schema,
          temperature: 0.0,
        },
      });

      const jsonText = response.text.trim();
      const result = JSON.parse(jsonText);

      if (
        result &&
        typeof result.bestSheetName === 'string' &&
        typeof result.bestHeaderRow === 'number' &&
        sheetPreviews.some(p => p.sheetName === result.bestSheetName) &&
        result.bestHeaderRow > 0
      ) {
        return result; 
      } else {
        throw new Error("Invalid response from AI model.");
      }
    } catch (error) {
      retries--;
      console.error(`Error analyzing sheet layout (retry ${totalRetries - retries} of ${totalRetries}):`, error);
      const errorString = JSON.stringify(error);
      if (retries > 0 && errorString.includes('429')) {
        const jitter = Math.random() * 1000;
        console.warn(`Rate limit hit on analyzeSheetLayout. Retrying in ${Math.round((delay + jitter) / 1000)}s...`);
        await new Promise(resolve => setTimeout(resolve, delay + jitter));
        delay *= 2;
      } else if (retries > 0) {
        await new Promise(resolve => setTimeout(resolve, 500));
      }
    }
  }

  console.warn("All retries failed for analyzeSheetLayout. Falling back to default.");
  return {
    bestSheetName: sheetPreviews[0]?.sheetName || '',
    bestHeaderRow: 1,
  };
}

function performStaticMapping(mappableFields: string[], fileHeaders: string[]): Record<string, string> {
  const mapping: Record<string, string> = {};
  const availableHeaders = [...fileHeaders];

  for (const field of mappableFields) {
    let bestMatch = 'N/A';
    let highestScore = -1;

    const fieldWords = new Set(field.toLowerCase().replace(/[_-]/g, ' ').split(/\s+/).filter(w => w.length > 2));

    for (const header of availableHeaders) {
      if (!header) continue;

      let currentScore = 0;
      const headerLower = header.toLowerCase();

      if (headerLower === field.toLowerCase()) {
        currentScore = 100;
      } else if (headerLower.includes(field.toLowerCase()) || field.toLowerCase().includes(headerLower)) {
        currentScore = 50;
      }

      const headerWords = new Set(headerLower.replace(/[_-]/g, ' ').split(/\s+/).filter(Boolean));
      let sharedWords = 0;
      for (const fWord of fieldWords) {
        if (headerWords.has(fWord)) {
          sharedWords++;
        }
      }
      currentScore += sharedWords * 10;

      if (currentScore > highestScore) {
        highestScore = currentScore;
        bestMatch = header;
      }
    }

    if (highestScore > 10) { 
        mapping[field] = bestMatch;
    } else {
        mapping[field] = 'N/A';
    }
  }

  return mapping;
}

