import React, { useState } from 'react';
import { UploadSummary, Rating } from '../types';
import RatingBadge from './RatingBadge';
import DonutChart from './DonutChart';

interface DashboardProps {
  history: UploadSummary[];
  onAnalyzeNew: () => void;
}

const StatCard: React.FC<{ title: string; value: string; icon: React.ReactNode }> = ({ title, value, icon }) => (
  <div className="bg-white p-6 rounded-lg shadow border border-gray-200 flex items-start">
    <div className="bg-blue-100 text-[#00629B] rounded-full p-3 mr-4">
      {icon}
    </div>
    <div>
      <h3 className="text-sm font-medium text-gray-500">{title}</h3>
      <p className="text-2xl font-bold text-gray-800">{value}</p>
    </div>
  </div>
);

const Dashboard: React.FC<DashboardProps> = ({ history, onAnalyzeNew }) => {
  const [expandedRow, setExpandedRow] = useState<string | null>(null);

  const totalRows = history.reduce((acc, curr) => acc + curr.rowCount, 0);

  const totalReliabilitySum = history.reduce((acc, curr) => acc + (curr.averageReliability * curr.rowCount), 0);
  const overallAverageReliability = totalRows > 0 ? Math.round(totalReliabilitySum / totalRows) : 0;

  const totalMatchedRows = history.reduce((acc, curr) => acc + (curr.rowCount * curr.matchPercentage / 100), 0);
  const overallMatchRate = totalRows > 0 ? Math.round((totalMatchedRows / totalRows) * 100) : 0;

  const overallRatingDistribution = history.reduce((acc: { [key in Rating]?: number }, curr) => {
    for (const rating in curr.ratingDistribution) {
      const key = rating as Rating;
      acc[key] = (acc[key] || 0) + (curr.ratingDistribution[key] || 0);
    }
    return acc;
  }, {});

  const allIssues = history.flatMap(h => h.commonIssues);
  const issueCounts = allIssues.reduce((acc, issueItem) => {
    if (issueItem.issue.toLowerCase().includes('analyzing') || issueItem.issue.toLowerCase().includes('error')) {
      return acc;
    }
    acc[issueItem.issue] = (acc[issueItem.issue] || 0) + issueItem.count;
    return acc;
  }, {} as Record<string, number>);

  const topIssues = Object.entries(issueCounts)
    .sort(([, countA], [, countB]) => (countB as number) - (countA as number))
    .slice(0, 5);

  return (
    <div className="space-y-8">
      {history.length > 0 && (
        <div className="flex justify-end">
            <button
            onClick={onAnalyzeNew}
            className="w-full sm:w-auto px-6 py-3 text-lg font-semibold text-white bg-[#00629B] rounded-md hover:bg-[#00497b] focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-[#00629B] transition-colors duration-200"
            >
            Upload Seafood Product Dataset
            </button>
        </div>
      )}

      {history.length > 0 ? (
        <>
            {/* Stats Grid */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                <StatCard title="Overall Match Rate" value={`${overallMatchRate}%`} icon={<svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>} />
                <StatCard title="Avg. Reliability" value={`${overallAverageReliability}%`} icon={<svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2"><path strokeLinecap="round" strokeLinejoin="round" d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z" /></svg>} />
                <StatCard title="Total Items Analyzed" value={totalRows.toLocaleString()} icon={<svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h7" /></svg>} />
                <StatCard title="Recent Uploads" value={history.length.toString()} icon={<svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12" /></svg>} />
            </div>

            {/* Main Content */}
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                <div className="lg:col-span-2 bg-white p-6 rounded-lg shadow-lg border border-gray-200">
                    <h2 className="text-xl font-bold text-gray-800 mb-4">Recent Activity</h2>
                    <div className="overflow-x-auto">
                        <table className="min-w-full divide-y divide-gray-200">
                            <thead className="bg-gray-50">
                                <tr>
                                    <th scope="col" className="px-2 py-3 w-12"><span className="sr-only">Expand</span></th>
                                    <th scope="col" className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">File Name</th>
                                    <th scope="col" className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Date</th>
                                    <th scope="col" className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Items</th>
                                    <th scope="col" className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Match Rate</th>
                                    <th scope="col" className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Avg. Reliability</th>
                                </tr>
                            </thead>
                            <tbody className="bg-white divide-y divide-gray-200">
                                {history.map(item => (
                                    <React.Fragment key={item.id}>
                                    <tr className="hover:bg-gray-50">
                                        <td className="px-2 py-4 whitespace-nowrap">
                                          <button 
                                            onClick={() => setExpandedRow(expandedRow === item.id ? null : item.id)}
                                            aria-expanded={expandedRow === item.id}
                                            aria-controls={`details-${item.id}`}
                                            className="p-1 rounded-full hover:bg-gray-200 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500"
                                          >
                                            <span className="sr-only">Toggle details for {item.fileName}</span>
                                            <svg xmlns="http://www.w3.org/2000/svg" className={`h-5 w-5 text-gray-500 transition-transform duration-200 ${expandedRow === item.id ? 'rotate-90' : ''}`} viewBox="0 0 20 20" fill="currentColor">
                                                <path fillRule="evenodd" d="M7.293 14.707a1 1 0 010-1.414L10.586 10 7.293 6.707a1 1 0 011.414-1.414l4 4a1 1 0 010 1.414l-4 4a1 1 0 01-1.414 0z" clipRule="evenodd" />
                                            </svg>
                                          </button>
                                        </td>
                                        <td className="px-4 py-4 whitespace-nowrap text-sm font-medium text-gray-900">{item.fileName}</td>
                                        <td className="px-4 py-4 whitespace-nowrap text-sm text-gray-500">{new Date(item.uploadDate).toLocaleString()}</td>
                                        <td className="px-4 py-4 whitespace-nowrap text-sm text-gray-500">{item.rowCount}</td>
                                        <td className="px-4 py-4 whitespace-nowrap text-sm text-gray-500">{item.matchPercentage.toFixed(0)}%</td>
                                        <td className="px-4 py-4 whitespace-nowrap text-sm text-gray-500">{item.averageReliability.toFixed(0)}%</td>
                                    </tr>
                                    {expandedRow === item.id && (
                                      <tr id={`details-${item.id}`}>
                                        <td colSpan={6} className="p-4 bg-gray-50 border-t">
                                          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                                            <div>
                                              <h4 className="font-semibold text-gray-700 mb-2">Rating Distribution</h4>
                                              <div className="flex flex-wrap gap-2">
                                                {Object.entries(item.ratingDistribution).map(([rating, count]) => (
                                                  <div key={rating} className="flex items-center gap-2 bg-white p-2 rounded-md border">
                                                    <RatingBadge rating={rating as Rating} />
                                                    <span className="font-bold text-gray-800">{count}</span>
                                                  </div>
                                                ))}
                                              </div>
                                            </div>
                                            <div>
                                              <h4 className="font-semibold text-gray-700 mb-2">Top Data Gaps in this File</h4>
                                              {item.commonIssues.length > 0 && item.commonIssues.some(i => !i.issue.toLowerCase().includes('error')) ? (
                                                <ul className="list-disc list-inside space-y-1 text-sm text-gray-600">
                                                  {item.commonIssues.map(issue => (
                                                    <li key={issue.issue}>
                                                      {issue.issue} ({issue.count} times)
                                                    </li>
                                                  ))}
                                                </ul>
                                              ) : (
                                                <p className="text-sm text-gray-500">No specific issues found.</p>
                                              )}
                                            </div>
                                          </div>
                                        </td>
                                      </tr>
                                    )}
                                    </React.Fragment>
                                ))}
                            </tbody>
                        </table>
                    </div>
                </div>

                <div className="space-y-8">
                  <div className="bg-white p-6 rounded-lg shadow-lg border border-gray-200">
                      <h2 className="text-xl font-bold text-gray-800 mb-4">Overall Rating Distribution</h2>
                      {totalRows > 0 ? (
                        <DonutChart data={overallRatingDistribution} total={totalRows} />
                      ) : <p className="text-sm text-gray-500">No data to display.</p> }
                  </div>
                  <div className="bg-white p-6 rounded-lg shadow-lg border border-gray-200">
                      <h2 className="text-xl font-bold text-gray-800 mb-4">Common Data Gaps</h2>
                      {topIssues.length > 0 ? (
                          <ul className="space-y-3">
                              {topIssues.map(([issue, count]) => (
                                  <li key={issue} className="text-sm text-gray-700">
                                      <p className="font-semibold">{issue}</p>
                                      <p className="text-gray-500">Occurred {count} times across all files</p>
                                  </li>
                              ))}
                          </ul>
                      ) : (
                          <p className="text-sm text-gray-500">No significant data gaps found in recent uploads. Great job!</p>
                      )}
                  </div>
                </div>
            </div>
        </>
      ) : (
         <div className="text-center bg-white p-12 rounded-lg shadow-lg border border-gray-200 flex flex-col items-center">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-16 w-16 text-gray-300 mb-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M9 17v-2m3 2v-4m3 4v-6m2 10H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
            </svg>
            <p className="text-gray-500 text-lg mb-6">You haven't analyzed any files yet.</p>
            <button
              onClick={onAnalyzeNew}
              className="w-full sm:w-auto px-8 py-4 text-lg font-semibold text-white bg-[#00629B] rounded-md hover:bg-[#00497b] focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-[#00629B] transition-colors duration-200 shadow-md"
            >
              Upload Seafood Product Dataset
            </button>
         </div>
      )}
    </div>
  );
};

